import {DEMO_PASSWORD,STORAGE_KEY,SESSION_KEY,MODULES,CASE_NAMES,QUESTIONS,createState,sampleEvidence,orderedLessons,moveLesson,publishedLessons,studentProgress,completeLesson,gradeQuiz,saveLesson,submitCase,reviewCase,validMediaUrl} from './academy-core.js';

const app=document.querySelector('#academy-app');
let state=createState(),session=null,loginRole=new URLSearchParams(location.search).get('role')==='tutor'?'tutor':'student',storageOk=true,toastTimer,urls=[];
let draftResources=[],draftVideo=null,draftCaseFiles=[];
try{const stored=JSON.parse(localStorage.getItem(STORAGE_KEY)||'null');if(stored?.version===2&&Array.isArray(stored.course?.lessons)&&Array.isArray(stored.students))state=stored;}catch{storageOk=false;}
try{const stored=JSON.parse(sessionStorage.getItem(SESSION_KEY)||'null');if(['student','tutor'].includes(stored?.role))session=stored;}catch{}
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paragraphs=value=>String(value||'').split(/\n\s*\n/).map(p=>`<p>${esc(p).replace(/\n/g,'<br>')}</p>`).join('');
const uid=()=>typeof crypto.randomUUID==='function'?crypto.randomUUID():Array.from(crypto.getRandomValues(new Uint8Array(16)),b=>b.toString(16).padStart(2,'0')).join('');
const student=()=>state.students.find(s=>s.id===session?.studentId)||state.students[0];
const badge=status=>`<span class="pill-status ${esc(status)}">${({empty:'Not started',draft:'Draft',published:'Published',submitted:'Awaiting review',approved:'Approved',changes:'Changes requested'})[status]||esc(status)}</span>`;
const cta=(label,href,light=false)=>`<a class="btn ${light?'light':''}" href="${href}">${label}<span aria-hidden="true">↗</span></a>`;
const quiet=(label,href)=>`<a class="portal-quiet" href="${href}">${label}</a>`;
const avatar=s=>`<span class="avatar">${esc(s.initials)}</span>`;
const tutorAvatar=()=>'<span class="avatar"><img src="/assets/pippin.jpg" alt="Pippin"></span>';
const progressBar=(p,label='Lessons completed')=>`<div class="portal-progress-label"><span>${label}</span><strong>${p.done} of ${p.total} · ${p.percent}%</strong></div><progress class="portal-progress" value="${p.done}" max="${Math.max(1,p.total)}" aria-label="${label}"></progress>`;
const stats=items=>`<div class="portal-stats ${items.length===4?'four':''}">${items.map(([v,l])=>`<div class="portal-stat"><strong>${v}</strong><span>${l}</span></div>`).join('')}</div>`;
function toast(message,error=false){if(!storageOk&&!error){message+=' These changes will last for this visit only because browser storage is unavailable.';error=true;}let el=document.querySelector('#portal-toast');el.textContent=message;el.classList.toggle('error',error);el.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>{el.hidden=true;},5500);}
function persist(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));return true;}catch{storageOk=false;toast('Changes are available for this visit only. Your browser could not save them.',true);return false;}}
function remember(){try{if(session)sessionStorage.setItem(SESSION_KEY,JSON.stringify(session));else sessionStorage.removeItem(SESSION_KEY);}catch{}}
function go(hash){if(location.hash==='#'+hash)render();else location.hash=hash;}
function signIn(role,studentId='amelia'){session={role,studentId};remember();go(role==='tutor'?'tutor':'student');}
function resetUrls(){urls.forEach(u=>URL.revokeObjectURL(u));urls=[];}
function published(){return publishedLessons(state);}
function pendingReviews(){return state.students.flatMap(s=>s.cases.filter(c=>c.status==='submitted').map(c=>({s,c})));}
function filesInState(){return [...state.course.lessons.flatMap(l=>[...(l.resources||[]),...(l.videoFile?[l.videoFile]:[])]),...state.students.flatMap(s=>s.cases.flatMap(c=>c.files))];}
function openDb(){return new Promise((resolve,reject)=>{const req=indexedDB.open('snippity-academy-demo-files',1);req.onupgradeneeded=()=>req.result.createObjectStore('files');req.onerror=()=>reject(new Error('File storage is unavailable in this browser.'));req.onsuccess=()=>resolve(req.result);});}
async function saveFile(file,kind='resource'){
 const max=kind==='video'?25:10;const supported=kind==='video'?file.type==='video/mp4':/^(application\/pdf|image\/(jpeg|png|webp)|text\/plain)$/.test(file.type);
 if(!supported)throw Error(kind==='video'?'Choose an MP4 video.':'Choose a PDF, JPG, PNG, WebP or text file.');
 if(file.size>max*1024*1024)throw Error(`Choose a file smaller than ${max} MB for this demo.`);
 const meta={id:uid(),name:file.name,type:file.type,size:file.size};const db=await openDb();
 await new Promise((resolve,reject)=>{const tx=db.transaction('files','readwrite');tx.objectStore('files').put(file,meta.id);tx.oncomplete=resolve;tx.onerror=()=>reject(new Error('Your browser could not save that file. Try a smaller one.'));});db.close();return meta;
}
async function getFileUrl(meta){if(meta.url)return meta.url;const db=await openDb();const file=await new Promise((resolve,reject)=>{const req=db.transaction('files').objectStore('files').get(meta.id);req.onsuccess=()=>resolve(req.result);req.onerror=reject;});db.close();if(!file)throw Error('This file is no longer available in this browser. Please add it again.');const url=URL.createObjectURL(file);urls.push(url);return url;}
function resourceLink(file){return file.url?`<a class="resource-link" href="${esc(file.url)}" target="_blank" rel="noopener noreferrer"><span>↧ &nbsp; ${esc(file.name)}</span><small>Open resource ↗</small></a>`:`<a class="resource-link" href="#" data-file="${esc(file.id)}" target="_blank" rel="noopener noreferrer" aria-disabled="true"><span>↧ &nbsp; ${esc(file.name)}</span><small>Open resource ↗</small></a>`;}
function header(){return `<header class="portal-header"><a class="brand" href="/academy.html"><img src="/assets/salon-logo.png" alt="" width="58" height="58"><span class="wordmark"><strong>The Snippity Pip</strong><small>The training academy</small></span></a><div class="portal-header-actions"><a href="/academy.html">← Back to the website</a>${session?`<button class="portal-quiet" data-action="switch">${session.role==='tutor'?'View as student':'Switch to tutor'} ↔</button><div class="portal-profile">${session.role==='tutor'?tutorAvatar():avatar(student())}<div><strong>${session.role==='tutor'?'Pippin':esc(student().name)}</strong><small>${session.role==='tutor'?'Tutor demo account':'Student demo account'}</small></div></div>`:''}</div></header><div class="portal-demo"><strong>Interactive academy demo</strong>Example accounts. Lessons, files and feedback stay in this browser; nothing is sent to a real tutor.</div>${storageOk?'':'<div class="storage-alert">Browser storage is unavailable. Changes will last for this visit only.</div>'}`;}
function sidebar(route){const isTutor=session.role==='tutor';const links=isTutor?[['tutor','⌂','Overview'],['builder','▤','Course builder'],['students','◌','Students'],['reviews','✓','Review work']]:[['student','⌂','My learning'],['learn','▷','My course'],['quiz','✓','Knowledge check'],['cases','▤','Case studies'],['resources','↧','My resources'],['certificate','✧','Certificate']];return `<aside class="portal-sidebar"><div class="account-label">${isTutor?'Tutor workspace':'Your learning space'}</div><nav aria-label="Academy navigation">${links.map(([path,icon,name])=>`<a href="#${path}" class="${route===path||(path==='builder'&&route==='editor')||(path==='reviews'&&route==='review')||(path==='cases'&&route==='case')?'active':''}"><span class="nav-symbol" aria-hidden="true">${icon}</span>${name}${path==='reviews'&&pendingReviews().length?` <span>(${pendingReviews().length})</span>`:''}</a>`).join('')}<a href="#login" data-action="signout"><span class="nav-symbol" aria-hidden="true">↪</span>Sign out</a></nav><div class="portal-sidebar-bottom"><p>A little practice.<br>A lot of possibility.</p><button data-action="reset">Reset the demonstration</button></div></aside>`;}
function shell(content,route){app.innerHTML=header()+`<div class="portal-shell">${sidebar(route)}<main class="portal-main" id="portal-main" tabindex="-1">${content}<div class="portal-footnote">Demonstration only · <button class="portal-quiet" data-action="reset" style="font-size:10px;min-height:26px;padding:4px 8px">Reset demo</button> · <a href="/privacy.html">Privacy information</a></div></main></div>`;bindCommon();}
function bindCommon(){
 app.querySelectorAll('[data-action="switch"]').forEach(b=>b.addEventListener('click',()=>signIn(session.role==='tutor'?'student':'tutor')));
 app.querySelectorAll('[data-action="signout"]').forEach(b=>b.addEventListener('click',e=>{e.preventDefault();session=null;remember();go('login');}));
 app.querySelectorAll('[data-action="reset"]').forEach(b=>b.addEventListener('click',()=>document.querySelector('#reset-dialog').showModal()));
 app.querySelectorAll('[data-file]').forEach(b=>{let error='';b.addEventListener('click',e=>{if(b.getAttribute('aria-disabled')==='true'){e.preventDefault();toast(error||'This file is still loading. Please try again in a moment.',true);}});const meta=filesInState().find(f=>f.id===b.dataset.file);if(!meta){error='Resource not found.';return;}getFileUrl(meta).then(url=>{b.href=url;b.removeAttribute('aria-disabled');}).catch(e=>{error=e.message;b.querySelector('small').textContent='File unavailable';});});
 app.querySelectorAll('[data-preview-student]').forEach(b=>b.addEventListener('click',()=>signIn('student',b.dataset.previewStudent)));
}
function renderLogin(){
 const tutor=loginRole==='tutor',email=tutor?'tutor@example.com':'student@example.com';
 app.innerHTML=header()+`<main class="portal-login" id="portal-main" tabindex="-1"><section class="login-story"><img class="login-logo" src="/assets/academy-logo.png" alt="The Snippity Pip Training Academy"><span class="eyebrow">A space to learn. A place to grow.</span><h1>Your next chapter<br><em>starts here.</em></h1><p class="lead">A first look at life inside the academy. Explore a student’s journey, then step into Pippin’s tutor workspace.</p><div class="login-steps"><div class="login-step"><span>01</span><div><strong>Learn in your own space.</strong><p>Video lessons, downloadable resources and progress you can pick up later.</p></div></div><div class="login-step"><span>02</span><div><strong>Put your skills into practice.</strong><p>Try a knowledge check and submit four example case studies.</p></div></div><div class="login-step"><span>03</span><div><strong>Grow with feedback.</strong><p>The tutor reviews work, gives feedback and approves completion.</p></div></div></div></section><section class="login-box"><div class="login-tabs" role="tablist" aria-label="Choose an example account"><button role="tab" data-login-role="student" aria-selected="${!tutor}">Student login</button><button role="tab" data-login-role="tutor" aria-selected="${tutor}">Tutor login</button></div><span class="eyebrow">${tutor?'For the educator':'For the learner'}</span><h2>${tutor?'Welcome back, Pippin.':'Welcome to your academy.'}</h2><p>${tutor?'Add lessons, publish resources and review your students’ work.':'Sign in as Amelia and explore her course from the inside.'}</p><div class="demo-credentials"><strong>USE THIS EXAMPLE ACCOUNT</strong><p>Email: <b>${email}</b></p><p>Password: <b>${DEMO_PASSWORD}</b></p><button id="fill-login" type="button">Fill in the example details →</button></div><form id="login-form"><div class="field"><label for="demo-email">Email address</label><input id="demo-email" type="email" name="email" required autocomplete="off" placeholder="${email}"></div><div class="field"><label for="demo-password">Password</label><div class="password-field"><input id="demo-password" name="password" type="password" required autocomplete="off"><button type="button" id="show-password" aria-label="Show example password">Show</button></div></div><button class="btn" type="submit">Sign in to the ${tutor?'tutor workspace':'student account'} <span aria-hidden="true">↗</span></button><p class="login-error" id="login-error" role="alert"></p></form><p class="login-footnote">These are sample credentials for a demonstration, not secure live accounts. Please use the example details rather than a personal password.</p></section></main>`;
 app.querySelectorAll('[data-login-role]').forEach(b=>b.addEventListener('click',()=>{loginRole=b.dataset.loginRole;renderLogin();}));
 document.querySelector('#fill-login').addEventListener('click',()=>{document.querySelector('#demo-email').value=email;document.querySelector('#demo-password').value=DEMO_PASSWORD;});
 document.querySelector('#show-password').addEventListener('click',e=>{const field=document.querySelector('#demo-password');field.type=field.type==='password'?'text':'password';e.target.textContent=field.type==='password'?'Show':'Hide';e.target.setAttribute('aria-label',field.type==='password'?'Show example password':'Hide example password');});
 document.querySelector('#login-form').addEventListener('submit',e=>{e.preventDefault();const data=new FormData(e.target);if(data.get('email').trim().toLowerCase()!==email||data.get('password')!==DEMO_PASSWORD){document.querySelector('#login-error').textContent='Use the example email and password shown above, or select “Fill in the example details”.';return;}signIn(loginRole);});
}
function journey(p){return `<div class="journey">${[[p.done===p.total&&p.total>0,'Lessons',`${p.done}/${p.total} complete`],[p.quizPassed,'Knowledge','Check understanding'],[p.approved===4,'Case studies',`${p.approved}/4 approved`],[p.ready,'Completion','Tutor sign-off']].map(([done,label,detail],i)=>`<div class="journey-step ${done?'done':''}"><span>${done?'✓':i+1}</span><strong>${label}</strong><small>${detail}</small></div>`).join('')}</div>`;}
function renderStudent(){const s=student(),p=studentProgress(state,s),next=published().find(l=>!s.completed.includes(l.id))||published()[0];const feedback=s.cases.filter(c=>c.feedback).at(-1);
 shell(`<div class="portal-title-row"><div><span class="eyebrow">Your learning space</span><h1>Hello, ${esc(s.name.split(' ')[0])}.</h1><p>A little progress today. A little more confidence tomorrow.</p></div><span class="pill-status">Student account · example</span></div><section class="portal-welcome"><div><span class="eyebrow">Keep your next chapter moving</span><h2>${p.ready?'Look how far you’ve come.':'There’s something good ahead.'}</h2><p>${p.ready?'Your lessons, knowledge check and four case studies are complete in this demonstration.':'Your course, your pace. Pick up your next lesson and build on what you’ve already learned.'}</p>${cta(p.ready?'View your example certificate':'Continue learning',p.ready?'#certificate':`#learn/${next?.id||''}`)}</div><img src="/assets/academy-logo.png" alt="The Snippity Pip Training Academy"></section>${stats([[`${p.done}<small style="font:14px var(--sans)"> / ${p.total}</small>`,'Lessons complete'],[p.quizPassed?'Passed':s.quiz?`${s.quiz.score} / 3`:'To do','Knowledge check'],[`${p.approved}<small style="font:14px var(--sans)"> / 4</small>`,'Case studies approved']])}<div class="portal-grid"><section class="portal-panel"><div class="course-cover"><div><span class="eyebrow">Your enrolled course · example</span><h2>${esc(state.course.title)}</h2><p>Six modules · Four practical case studies</p></div><img src="/assets/academy-logo.png" alt=""></div>${progressBar(p)}<div class="course-next">${p.done===p.total?'Lessons explored. Ready for the next step?':'Up next'}<strong>${p.done===p.total?'Complete your knowledge check and practical work.':esc(next?.title||'Your course')}</strong></div>${cta(p.done===p.total?'Go to the knowledge check':'Open your course',p.done===p.total?'#quiz':`#learn/${next?.id||''}`)}${journey(p)}</section><aside><section class="portal-panel"><div class="portal-profile">${tutorAvatar()}<div><strong>A note from Pippin</strong><small>Example tutor welcome</small></div></div><p class="tutor-note">${esc(state.announcement)}</p><hr class="portal-divider"><h3>Your next milestone</h3><p class="muted">${p.done<p.total?'Work through the lessons, then test your understanding with three short questions.':!p.quizPassed?'Complete the knowledge check before finishing your four case studies.':'Prepare your practical case studies and send them to the demo review queue.'}</p>${quiet('See your case studies','#cases')}</section>${feedback?`<section class="portal-panel"><span class="eyebrow">Latest tutor feedback</span><h3>${esc(feedback.title)}</h3>${badge(feedback.status)}<p class="tutor-note">${esc(feedback.feedback)}</p>${quiet('View feedback',`#case/${feedback.id}`)}</section>`:''}</aside></div>`,'student');
}
function renderTutor(){const queue=pendingReviews();shell(`<div class="portal-title-row"><div><span class="eyebrow">Your tutor workspace</span><h1>Welcome back, Pippin.</h1><p>A clear view of your courses, your learners and their next steps.</p></div><div class="portal-title-actions">${cta('Add course material','#editor/new')}</div></div>${stats([[state.students.length,'Example students'],[published().length,'Published lessons'],[queue.length,'Case studies to review'],[state.students.filter(s=>studentProgress(state,s).ready).length,'Students ready to complete']])}<div class="portal-grid"><div><section class="portal-panel"><div class="panel-head"><h2>Your course</h2><a href="#builder">Manage course →</a></div><div class="course-cover" style="margin:0 0 25px"><div><span class="eyebrow">Training academy</span><h2>${esc(state.course.title)}</h2><p>${published().length} published lessons · ${state.course.lessons.filter(l=>l.status==='draft').length} drafts</p></div><img src="/assets/academy-logo.png" alt=""></div><p class="muted">Add teaching videos, write lesson notes and attach workbooks. Publish when you’re ready for students to see them.</p><div class="actions">${cta('Open course builder','#builder')}${quiet('View student experience','#student-preview')}</div></section><section class="portal-panel"><div class="panel-head"><h2>Ready for your feedback</h2><a href="#reviews">View all →</a></div>${queue.length?`<table class="portal-table"><thead><tr><th>Student</th><th>Case study</th><th></th></tr></thead><tbody>${queue.slice(0,3).map(({s,c})=>`<tr><td><strong>${esc(s.name)}</strong><small>Example learner</small></td><td>${esc(c.title)}</td><td>${quiet('Review',`#review/${s.id}/${c.id}`)}</td></tr>`).join('')}</tbody></table>`:'<div class="portal-empty">Your review queue is clear. New submissions will appear here.</div>'}</section></div><aside><section class="portal-panel"><span class="eyebrow">From tutor to student</span><h2>See the whole journey.</h2><ol class="portal-info-list"><li>Add or edit a lesson in the course builder.</li><li>Save it as a draft, then publish it.</li><li>Switch to the student account to see the change.</li><li>Submit a case study, then switch back to review it.</li></ol><div class="portal-callout">Both accounts share the same demo in this browser, so your changes follow you between views.</div></section><section class="portal-panel"><div class="panel-head"><h3>Student welcome note</h3></div><form id="announcement-form"><label class="sr-only" for="announcement">Welcome message</label><textarea id="announcement" name="message" required maxlength="600" style="font-size:12px;min-height:145px">${esc(state.announcement)}</textarea><button class="portal-quiet" type="submit" style="margin-top:12px">Update welcome note</button></form></section></aside></div>`,'tutor');document.querySelector('#announcement-form').addEventListener('submit',e=>{e.preventDefault();state.announcement=new FormData(e.target).get('message').trim();persist();toast('Welcome note updated in the student account.');});}

function lessonSidebar(current){const s=student(),p=studentProgress(state,s);return `<aside class="portal-lessons"><div class="lesson-side-head"><span class="eyebrow">Your course</span><h2>${esc(state.course.title)}</h2>${progressBar(p)}</div>${MODULES.map((m,i)=>{const ls=published().filter(l=>l.module===i);return (ls.length||i===5)?`<div class="module-name">0${i+1} / ${m}</div>${ls.map(l=>`<a href="#learn/${l.id}" class="portal-lesson-link ${l.id===current?'active':''}"><span class="lesson-dot ${s.completed.includes(l.id)?'checked':''}">${s.completed.includes(l.id)?'✓':''}</span><span>${esc(l.title)}<small>${l.type==='video'?'Video & notes':'Lesson notes'} · ${l.minutes} min</small></span></a>`).join('')}${i===5?`<a class="portal-lesson-link" href="#quiz"><span class="lesson-dot ${s.quiz?.passed?'checked':''}">${s.quiz?.passed?'✓':''}</span><span>Knowledge check<small>3 questions</small></span></a><a class="portal-lesson-link" href="#cases"><span class="lesson-dot ${p.approved===4?'checked':''}">${p.approved===4?'✓':''}</span><span>Your case studies<small>4 practical submissions</small></span></a>`:''}`:'';}).join('')}</aside>`;}
function mediaMarkup(l){if(l.type!=='video')return '';if(l.videoFile)return `<div class="lesson-media"><video controls playsinline preload="metadata" id="lesson-video" aria-label="${esc(l.title)} video"></video></div>`;if(l.videoUrl){let src=l.videoUrl;try{const u=new URL(src,location.origin);let yt=null;if(u.hostname==='youtu.be')yt=u.pathname.slice(1);if(['youtube.com','www.youtube.com'].includes(u.hostname))yt=u.searchParams.get('v');if(yt&&/^[\w-]{11}$/.test(yt))return `<div class="lesson-media"><iframe src="https://www.youtube-nocookie.com/embed/${yt}" title="${esc(l.title)}" allow="fullscreen" allowfullscreen loading="lazy"></iframe></div>`;}catch{}return `<div class="lesson-media"><video controls playsinline preload="metadata" src="${esc(src)}" aria-label="${esc(l.title)} video"></video></div>`;}return '<div class="portal-callout">This video lesson currently has written notes. Your tutor can add the video in the course builder.</div>';}
function renderLesson(id){const s=student(),lessons=published(),l=lessons.find(l=>l.id===id)||lessons.find(l=>!s.completed.includes(l.id))||lessons[0];if(!l){shell('<div class="portal-empty"><h1>Your course is being prepared.</h1><p>Published lessons will appear here.</p></div>','learn');return;}const next=lessons[lessons.findIndex(x=>x.id===l.id)+1];
 shell(`<a class="portal-back" href="#student">← Back to my learning</a><div class="portal-course-layout">${lessonSidebar(l.id)}<article class="portal-lesson"><span class="eyebrow">Module 0${l.module+1} · ${MODULES[l.module]}</span><h1>${esc(l.title)}</h1><div class="lesson-meta"><span>${l.type==='video'?'Video lesson':'Read & reflect'}</span><span>${l.minutes} min learning time</span>${s.completed.includes(l.id)?'<span>✓ Completed</span>':''}</div>${mediaMarkup(l)}<div class="lesson-body">${paragraphs(l.body)}</div>${l.resources?.length?`<section class="lesson-resources"><h2>Keep these close.</h2>${l.resources.map(resourceLink).join('')}</section>`:''}<div class="portal-notes"><label for="lesson-notes">My learning notes</label><textarea id="lesson-notes" maxlength="5000" placeholder="What will you take from this lesson?">${esc(s.notes[l.id]||'')}</textarea><button id="save-notes" class="portal-quiet">Save my notes</button></div><div class="portal-lesson-actions"><button class="btn" id="complete-lesson">${s.completed.includes(l.id)?'Continue to the next step':'Mark complete & continue'} <span aria-hidden="true">→</span></button>${next?`<a class="portal-back" style="margin:0" href="#learn/${next.id}">Skip to next lesson →</a>`:''}</div></article></div>`,'learn');
 document.querySelector('#save-notes').addEventListener('click',()=>{s.notes[l.id]=document.querySelector('#lesson-notes').value;persist();toast('Your learning notes are saved.');});
 document.querySelector('#complete-lesson').addEventListener('click',()=>{s.notes[l.id]=document.querySelector('#lesson-notes').value;completeLesson(state,s.id,l.id);persist();go(next?`learn/${next.id}`:'quiz');});
 if(l.videoFile)getFileUrl(l.videoFile).then(url=>{const v=document.querySelector('#lesson-video');if(v)v.src=url;}).catch(e=>toast(e.message,true));
}
function renderQuiz(result=null){const s=student();shell(`<a class="portal-back" href="#learn">← Back to my course</a><div class="portal-title-row"><div><span class="eyebrow">Module 06 · Check your understanding</span><h1>Bring it all together.</h1><p>Three sample questions before your practical case studies.</p></div>${s.quiz?.passed?badge('approved'):''}</div><div class="portal-grid"><section class="portal-panel">${result?`<div class="quiz-result"><h2>${result.passed?'Nicely done.':'A little more practice.'}</h2><p>You scored ${result.score} out of 3. ${result.passed?'Your knowledge check is complete in this demo.':'Review the feedback below, then try again. You need all three answers correct.'}</p></div>`:s.quiz?`<div class="portal-callout">Your latest score: <strong>${s.quiz.score} out of 3</strong>. ${s.quiz.passed?'You can revisit these questions whenever you like.':'You can try again below.'}</div>`:''}<form id="quiz-form">${QUESTIONS.map((q,i)=>`<fieldset class="quiz-question"><legend>${i+1}. ${q.question}</legend>${q.options.map((opt,j)=>`<label class="portal-quiz-choice"><input type="radio" name="q${i}" value="${j}" required>${opt}</label>`).join('')}${result?`<p class="small muted">${q.explanation}</p>`:''}</fieldset>`).join('')}<button class="btn" type="submit">Check my answers <span aria-hidden="true">→</span></button></form></section><aside class="portal-panel"><span class="eyebrow">Your next step</span><h2>From knowing<br>to doing.</h2><p class="muted">Your four case studies bring together the consultation, your planned finish and a reflection on the result.</p>${cta('Explore case studies','#cases')}<div class="portal-callout">The questions are examples for this demonstration. The real course’s assessment and pass requirements will be confirmed before enrolment.</div></aside></div>`,'quiz');
 document.querySelector('#quiz-form').addEventListener('submit',e=>{e.preventDefault();const data=new FormData(e.target);const result=gradeQuiz(QUESTIONS.map((q,i)=>data.get('q'+i)));s.quiz=result;persist();renderQuiz(result);document.querySelector('.quiz-result').scrollIntoView({behavior:'smooth',block:'center'});});
}
function renderCases(){const s=student(),p=studentProgress(state,s);shell(`<div class="portal-title-row"><div><span class="eyebrow">Module 06 · Put it into practice</span><h1>Your case studies.</h1><p>Four opportunities to reflect, share your work and grow with feedback.</p></div><span class="pill-status">${p.approved} of 4 approved</span></div><div class="portal-callout"><strong>Try the whole feedback loop.</strong> Use the example evidence file to submit a case study, switch to the tutor account and review it, then return here to see the feedback. Use sample information only.</div><div class="case-grid">${s.cases.map((c,i)=>`<article class="case-card"><div class="panel-head"><span class="eyebrow mb-0">Case study 0${i+1}</span>${badge(c.status)}</div><h2>${esc(c.title)}</h2><p>${c.status==='empty'?'Record your plan, add evidence and reflect on the result.':c.status==='submitted'?'Your example submission is in the tutor’s review queue.':c.status==='changes'?'Your tutor has left some feedback to help you take the next step.':'Your tutor has approved this case study in the demo.'}</p>${c.feedback?`<div class="feedback-preview"><strong>Tutor feedback</strong><br>${esc(c.feedback)}</div>`:''}${quiet(c.status==='empty'?'Start case study':c.status==='changes'?'View feedback & resubmit':'View case study',`#case/${i}`)}</article>`).join('')}</div>`,'cases');}
function fileChips(list,target,removeHandler){const el=document.querySelector(target);if(!el)return;el.innerHTML=list.length?list.map((f,i)=>`<div class="attachment-chip"><span>▤ &nbsp; ${esc(f.name)}</span><button type="button" data-remove-file="${i}" aria-label="Remove ${esc(f.name)}">×</button></div>`).join(''):'<p class="small muted">No files added yet.</p>';el.querySelectorAll('[data-remove-file]').forEach(b=>b.addEventListener('click',()=>removeHandler(Number(b.dataset.removeFile))));}
function renderCase(index){const s=student(),c=s.cases[index];if(!c){go('cases');return;}draftCaseFiles=structuredClone(c.files);shell(`<a class="portal-back" href="#cases">← Back to case studies</a><div class="portal-title-row"><div><span class="eyebrow">Case study 0${index+1}</span><h1>${esc(c.title)}</h1><p>Your plan, your evidence and what you learned.</p></div>${badge(c.status)}</div><div class="portal-editor"><form class="portal-panel" id="case-form">${c.feedback?`<div class="portal-callout"><strong>Feedback from Pippin</strong><p>${esc(c.feedback)}</p></div>`:''}<div class="field"><label for="model-reference">Anonymous practice model reference</label><input id="model-reference" name="model" required maxlength="100" placeholder="For example, Practice model A" value="${esc(c.model)}"><p class="field-help">Use a sample reference, not a client’s name or personal details.</p></div><div class="field"><label for="case-reflection">Your reflection</label><textarea id="case-reflection" name="notes" required minlength="20" maxlength="5000" placeholder="What was your plan? What worked well? What would you refine next time?">${esc(c.notes)}</textarea></div><div class="file-zone"><label for="case-files">Add your evidence</label><input id="case-files" type="file" accept="image/jpeg,image/png,image/webp,application/pdf" multiple><p>JPG, PNG, WebP or PDF · Up to 10 MB per file · Stored in this browser.</p></div><div id="case-file-list"></div><button class="portal-quiet" type="button" id="sample-evidence">Use example evidence & reflection</button><p class="form-error" role="alert" id="case-error"></p><div class="actions"><button class="btn" type="submit">${c.status==='empty'?'Submit to demo tutor':'Resubmit to demo tutor'} <span aria-hidden="true">→</span></button>${quiet('Back to case studies','#cases')}</div></form><aside class="portal-panel"><span class="eyebrow">A thoughtful reflection</span><h2>Show your thinking.</h2><ul class="portal-info-list"><li>The finish you planned and why.</li><li>What you observed during your practice.</li><li>The outcome compared with your plan.</li><li>One thing to develop next time.</li></ul><div class="portal-callout">The “Use example” button gives you a sample reflection and clearly labelled evidence to try the review process.</div><p class="sidebar-tip">This is a local demonstration. Files are not uploaded to a real student record or sent to Pippin.</p></aside></div>`,'case');
 const update=()=>fileChips(draftCaseFiles,'#case-file-list',i=>{draftCaseFiles.splice(i,1);update();});update();
 document.querySelector('#sample-evidence').addEventListener('click',()=>{if(!draftCaseFiles.some(f=>f.id==='sample-evidence'))draftCaseFiles.push(sampleEvidence());document.querySelector('#model-reference').value='Practice model A';document.querySelector('#case-reflection').value='I planned the finish around the practice model’s requested look. I recorded my preparation, compared the result with the plan and noted the finishing details. I was pleased with the overall movement. Next time I would give myself more time to refine the shape and explain aftercare clearly.';update();});
 document.querySelector('#case-files').addEventListener('change',async e=>{const btn=document.querySelector('#case-form button[type="submit"]');btn.disabled=true;try{for(const file of e.target.files)draftCaseFiles.push(await saveFile(file));update();toast('Evidence saved in this browser.');}catch(err){toast(err.message,true);}finally{btn.disabled=false;e.target.value='';}});
 document.querySelector('#case-form').addEventListener('submit',e=>{e.preventDefault();try{const data=new FormData(e.target);submitCase(state,s.id,index,{model:data.get('model'),notes:data.get('notes'),files:draftCaseFiles});persist();go('cases');toast('Case study added to the demo tutor’s review queue.');}catch(err){document.querySelector('#case-error').textContent=err.message;}});
}
function renderResources(){const files=[...new Map(published().flatMap(l=>l.resources||[]).map(f=>[f.id,f])).values()];shell(`<div class="portal-title-row"><div><span class="eyebrow">Your course toolkit</span><h1>Keep your learning close.</h1><p>Download the workbooks and resources attached to your published lessons.</p></div></div><section class="portal-panel">${files.length?files.map(resourceLink).join(''):'<div class="portal-empty">Your tutor has not added resources yet.</div>'}<div class="portal-callout">New resources appear here when the tutor publishes them. The included workbook is an example for this demonstration.</div></section>`,'resources');}
function renderCertificate(){const s=student(),p=studentProgress(state,s);shell(p.ready?`<div class="portal-title-row"><div><span class="eyebrow">Your next chapter</span><h1>Look how far you’ve come.</h1></div><button class="portal-quiet" id="print-certificate">Print example certificate ↗</button></div><section class="certificate-paper"><img src="/assets/academy-logo.png" alt="The Snippity Pip Training Academy"><span class="eyebrow">An example of the final milestone</span><h1>Certificate of completion</h1><p>This demonstration recognises</p><div class="student-name">${esc(s.name)}</div><p>for completing the example learning journey for</p><h2>${esc(state.course.title)}</h2><p>${p.total} lessons · Knowledge check · Four approved case studies</p><div class="signature">The Snippity Pip Training Academy</div><div class="demo-stamp">DEMONSTRATION ONLY — NOT A QUALIFICATION</div><p class="small">An illustrative certificate, with no accreditation or qualification status.</p></section>`:`<div class="portal-title-row"><div><span class="eyebrow">Your final milestone</span><h1>A little further to go.</h1><p>Your example certificate becomes available when each step is complete.</p></div></div><section class="portal-panel certificate-locked"><span style="font-size:40px;color:var(--gold)" aria-hidden="true">✧</span><h2>Build towards your achievement.</h2><div class="checklist"><div><span>${p.done===p.total?'✓':'○'}</span>Complete all published lessons (${p.done}/${p.total})</div><div><span>${p.quizPassed?'✓':'○'}</span>Pass the sample knowledge check</div><div><span>${p.approved===4?'✓':'○'}</span>Receive tutor approval for four case studies (${p.approved}/4)</div></div>${cta('Continue your course','#learn')}<hr class="portal-divider"><p class="muted">Want to see the finished journey? Grace is a separate, completed example learner.</p><button class="portal-quiet" id="preview-certificate">View Grace’s completed example</button></section>`,'certificate');
 document.querySelector('#print-certificate')?.addEventListener('click',()=>window.print());document.querySelector('#preview-certificate')?.addEventListener('click',()=>{session={role:'student',studentId:'grace'};remember();renderCertificate();});}

function renderBuilder(){const lessons=orderedLessons(state);shell(`<div class="portal-title-row"><div><span class="eyebrow">Tutor workspace · Course builder</span><h1>A place for your knowledge.</h1><p>Arrange the learning, add your material and publish it for your students.</p></div><div class="portal-title-actions">${cta('Add a lesson','#editor/new')}</div></div><section class="portal-panel"><div class="panel-head"><div><h2>${esc(state.course.title)}</h2><p class="small muted" style="margin:8px 0 0">${published().length} published lessons · ${lessons.filter(l=>l.status==='draft').length} drafts</p></div>${quiet('Preview as student','#student-preview')}</div>${lessons.map((l,i)=>`<div class="curriculum-row"><span class="row-num">${String(i+1).padStart(2,'0')}</span><div><strong>${esc(l.title)}</strong><small>${MODULES[l.module]} · ${l.type==='video'?'Video & notes':'Lesson notes'} · ${l.minutes} min · ${(l.resources||[]).length} resources</small></div>${badge(l.status)}<div class="row-actions"><button data-move="${l.id}" data-direction="-1" ${i===0||lessons[i-1].module!==l.module?'disabled':''} aria-label="Move ${esc(l.title)} up">↑</button><button data-move="${l.id}" data-direction="1" ${i===lessons.length-1||lessons[i+1].module!==l.module?'disabled':''} aria-label="Move ${esc(l.title)} down">↓</button><a class="portal-quiet" href="#editor/${l.id}" style="min-height:31px;padding:5px 10px">Edit</a></div></div>`).join('')}</section><div class="portal-callout"><strong>Draft first, publish when you’re ready.</strong> Students only see published lessons. Updating a lesson resets its completion mark so students can review the new material. Use the arrows to change lesson order within each module.</div>`,'builder');
 app.querySelectorAll('[data-move]').forEach(b=>b.addEventListener('click',()=>{if(moveLesson(state,b.dataset.move,Number(b.dataset.direction))){persist();renderBuilder();}}));}
function renderEditor(id){const existing=state.course.lessons.find(l=>l.id===id);const l=existing||{id:uid(),title:'',body:'',module:4,minutes:5,type:'reading',status:'draft',videoUrl:'',videoFile:null,resources:[]};draftResources=structuredClone(l.resources||[]);draftVideo=l.videoFile?structuredClone(l.videoFile):null;
 shell(`<a class="portal-back" href="#builder">← Back to course builder</a><div class="portal-title-row"><div><span class="eyebrow">Tutor workspace · ${existing?'Edit':'Create'} lesson</span><h1>${existing?'Shape the next lesson.':'Pass your knowledge on.'}</h1><p>Add your notes, video and downloads in one place.</p></div>${badge(l.status)}</div><form id="lesson-editor" class="portal-editor"><section class="portal-panel"><div class="field"><label for="lesson-title">Lesson title</label><input id="lesson-title" name="title" required maxlength="120" placeholder="For example, Choosing the right finishing products" value="${esc(l.title)}"></div><div class="portal-form-grid"><div class="field"><label for="lesson-module">Module</label><select id="lesson-module" name="module">${MODULES.map((m,i)=>`<option value="${i}" ${i===l.module?'selected':''}>0${i+1} / ${m}</option>`).join('')}</select></div><div class="field"><label for="lesson-time">Estimated learning time (minutes)</label><input id="lesson-time" name="minutes" type="number" min="1" max="240" required value="${l.minutes}"></div></div><div class="field"><label for="lesson-type">Lesson format</label><select id="lesson-type" name="type"><option value="reading" ${l.type==='reading'?'selected':''}>Lesson notes & resources</option><option value="video" ${l.type==='video'?'selected':''}>Video & lesson notes</option></select></div><div class="field"><label for="lesson-body">Lesson notes</label><textarea id="lesson-body" name="body" required maxlength="20000" placeholder="Explain the lesson, what students should focus on and any practice activity…">${esc(l.body)}</textarea><p class="field-help">Separate paragraphs with a blank line. Your notes appear below the teaching video.</p></div><div id="video-fields" ${l.type==='video'?'':'hidden'}><div class="field"><label for="video-url">Video link</label><input id="video-url" name="videoUrl" type="url" placeholder="https://… (MP4 or YouTube link)" value="${esc(l.videoUrl?.startsWith('/')?'':l.videoUrl||'')}"><p class="field-help">Use a direct HTTPS MP4 link or a YouTube watch link. Or add an MP4 file below.</p></div><div class="file-zone"><label for="video-upload">Add a teaching video</label><input id="video-upload" type="file" accept="video/mp4"><p>MP4 · Up to 25 MB for this browser demo.</p></div><div id="video-file-list"></div><button class="portal-quiet" id="use-sample-video" type="button">Use the example welcome video</button></div><h2 style="margin-top:32px">Downloads & workbooks</h2><div class="file-zone"><label for="resource-upload">Add lesson resources</label><input id="resource-upload" type="file" accept="application/pdf,image/jpeg,image/png,image/webp,text/plain" multiple><p>PDF, images or text · Up to 10 MB per file · Stored in this browser.</p></div><div id="resource-list"></div><button class="portal-quiet" id="add-workbook" type="button">Add the example workbook</button></section><aside class="portal-panel"><span class="eyebrow">Make it ready for learning</span><h2>From your idea<br>to their next skill.</h2><p class="sidebar-tip">A clear title, a few focused paragraphs and a useful resource can make a lesson easy to follow.</p><ul class="portal-info-list"><li><b>Save draft</b> keeps the lesson in your tutor workspace.</li><li><b>Publish lesson</b> makes it available in the student account.</li><li><b>Switch to student</b> in the header to see the result.</li></ul><div class="actions"><button class="btn" type="submit" name="action" value="published">Publish lesson <span aria-hidden="true">↗</span></button><button class="portal-quiet" type="submit" name="action" value="draft">Save draft</button></div><p id="editor-error" class="form-error" role="alert"></p><div class="portal-callout">Changes are part of the demo in this browser. Real video hosting and student accounts can be connected for the finished academy.</div>${existing?`<button class="portal-quiet danger" id="delete-lesson" type="button">Remove this lesson</button>`:''}</aside></form>`,'editor');
 let sampleVideo=l.videoUrl?.startsWith('/')?l.videoUrl:'';
 const updateResources=()=>fileChips(draftResources,'#resource-list',i=>{draftResources.splice(i,1);updateResources();});
 const updateVideo=()=>fileChips(draftVideo?[draftVideo]:sampleVideo?[{name:'Example welcome video.mp4'}]:[],'#video-file-list',()=>{draftVideo=null;sampleVideo='';updateVideo();});updateResources();updateVideo();
 document.querySelector('#lesson-type').addEventListener('change',e=>{document.querySelector('#video-fields').hidden=e.target.value!=='video';});
 document.querySelector('#video-url').addEventListener('input',()=>{draftVideo=null;sampleVideo='';updateVideo();});
 document.querySelector('#use-sample-video').addEventListener('click',()=>{sampleVideo='/assets/academy-welcome.mp4';draftVideo=null;document.querySelector('#video-url').value='';updateVideo();});
 document.querySelector('#add-workbook').addEventListener('click',()=>{if(!draftResources.some(f=>f.id==='starter-workbook'))draftResources.push({id:'starter-workbook',name:'Blow-dry practice workbook.pdf',url:'/assets/blow-dry-practice-workbook.pdf',type:'application/pdf',size:0});updateResources();});
 async function upload(e,kind){const buttons=[...document.querySelectorAll('#lesson-editor button[type="submit"]')];buttons.forEach(b=>b.disabled=true);try{for(const f of e.target.files){const meta=await saveFile(f,kind);if(kind==='video'){draftVideo=meta;sampleVideo='';document.querySelector('#video-url').value='';}else draftResources.push(meta);}updateResources();updateVideo();toast('File added to your draft in this browser.');}catch(err){toast(err.message,true);}finally{buttons.forEach(b=>b.disabled=false);e.target.value='';}}
 document.querySelector('#video-upload').addEventListener('change',e=>upload(e,'video'));document.querySelector('#resource-upload').addEventListener('change',e=>upload(e,'resource'));
 document.querySelector('#lesson-editor').addEventListener('submit',e=>{e.preventDefault();try{const data=new FormData(e.target);const videoUrl=data.get('videoUrl').trim();if(!validMediaUrl(videoUrl))throw Error('Use an HTTPS video link.');const status=e.submitter?.value==='published'?'published':'draft';saveLesson(state,{...l,title:data.get('title'),module:Number(data.get('module')),minutes:Number(data.get('minutes')),body:data.get('body'),type:data.get('type'),status,videoUrl:videoUrl||sampleVideo,videoFile:draftVideo,resources:draftResources});persist();go('builder');toast(status==='published'?'Lesson published. It is now visible in the student account.':'Draft saved. Students will see it after you publish.');}catch(err){document.querySelector('#editor-error').textContent=err.message;}});
 document.querySelector('#delete-lesson')?.addEventListener('click',()=>{const dialog=document.querySelector('#remove-dialog');dialog.querySelector('p').textContent=`Remove “${l.title}” from this demonstration? You can restore the starting examples with Reset demo.`;dialog.dataset.lesson=l.id;dialog.showModal();});
}
function renderStudents(){shell(`<div class="portal-title-row"><div><span class="eyebrow">Tutor workspace · Example learner records</span><h1>Every learner, a next step.</h1><p>See their progress and open an example student view.</p></div></div><section class="portal-panel"><div class="table-scroll"><table class="portal-table"><thead><tr><th>Student</th><th>Learning</th><th>Knowledge</th><th>Case studies</th><th></th></tr></thead><tbody>${state.students.map(s=>{const p=studentProgress(state,s);return `<tr><td><div class="person">${avatar(s)}<div><strong>${esc(s.name)}</strong><small>${esc(s.email)}</small></div></div></td><td>${p.done}/${p.total} lessons<small>${p.percent}% complete</small></td><td>${p.quizPassed?'Passed':'In progress'}</td><td>${p.approved}/4 approved<small>${s.cases.filter(c=>c.status==='submitted').length} awaiting review</small></td><td><button class="portal-quiet" data-preview-student="${s.id}">View account ↗</button></td></tr>`;}).join('')}</tbody></table></div></section><div class="portal-callout">These are fictional learner records. Amelia’s account is the main walkthrough; Sophie has sample work ready for review, and Grace shows a completed example.</div>`,'students');}
function renderReviews(studentId,caseIndex){const queue=pendingReviews();let selected=queue.find(x=>x.s.id===studentId&&x.c.id===Number(caseIndex))||queue[0];shell(`<div class="portal-title-row"><div><span class="eyebrow">Tutor workspace · Feedback & review</span><h1>A little guidance goes a long way.</h1><p>${queue.length} example ${queue.length===1?'submission is':'submissions are'} ready for your feedback.</p></div></div>${!selected?'<section class="portal-panel portal-empty"><h2>You’re all caught up.</h2><p>Switch to a student account and submit a case study to see it appear here.</p><a class="btn" href="#student-preview">Explore the student account ↗</a></section>':`<div class="review-layout"><aside>${queue.map(({s,c})=>`<a class="review-item ${s.id===selected.s.id&&c.id===selected.c.id?'active':''}" href="#review/${s.id}/${c.id}"><small>Case study 0${c.id+1}</small><strong>${esc(s.name)}</strong><span>${esc(c.title)}</span><br>${badge(c.status)}</a>`).join('')}</aside><section class="portal-panel"><div class="panel-head"><div><span class="eyebrow">Case study 0${selected.c.id+1}</span><h2>${esc(selected.c.title)}</h2></div>${avatar(selected.s)}</div><p class="small muted">${esc(selected.s.name)} · ${esc(selected.c.model)}</p><h3>Student reflection</h3><div class="student-reflection">${esc(selected.c.notes)}</div><h3 style="margin-top:28px">Evidence</h3>${selected.c.files.map(resourceLink).join('')}${selected.c.files.some(f=>f.id==='sample-evidence')?'<div class="review-evidence"><img src="/assets/example-case-study.svg" alt="Clearly labelled example before-and-after evidence placeholders"></div>':''}<form class="review-form" id="review-form"><label for="review-feedback">Your feedback to the student</label><textarea id="review-feedback" name="feedback" required maxlength="3000" placeholder="Explain what worked well and what the student should focus on next…"></textarea><button class="portal-quiet" id="example-feedback" type="button">Use example feedback</button><p id="review-error" class="form-error" role="alert"></p><div class="actions"><button class="btn" name="decision" value="approved" type="submit">Approve case study ✓</button><button class="portal-quiet" name="decision" value="changes" type="submit">Request changes</button></div><p class="small muted" style="margin:18px 0 0">Feedback appears in this example student account. No email is sent.</p></form></section></div>`}`,'reviews');if(!selected)return;
 document.querySelector('#example-feedback').addEventListener('click',()=>{document.querySelector('#review-feedback').value='A clear plan and a thoughtful reflection. You have linked the intended finish to your review of the result. Keep building on the finishing details you identified for next time.';});
 document.querySelector('#review-form').addEventListener('submit',e=>{e.preventDefault();try{reviewCase(state,selected.s.id,selected.c.id,e.submitter?.value,new FormData(e.target).get('feedback'));persist();renderReviews();toast('Review saved. The student can now see your feedback.');}catch(err){document.querySelector('#review-error').textContent=err.message;}});
}
function render(){resetUrls();let [route,id,caseIndex]=(location.hash.slice(1)||(session?session.role:'login')).split('/');
 if(route==='student-preview'){signIn('student');return;}
 if(!session||route==='login'){if(['tutor','builder','editor','reviews','review','students'].includes(route))loginRole='tutor';renderLogin();return;}
 const tutorOnly=['tutor','builder','editor','reviews','review','students'];
 if(tutorOnly.includes(route)&&session.role!=='tutor'){go('student');return;}
 if(!tutorOnly.includes(route)&&session.role==='tutor'){go('tutor');return;}
 switch(route){case 'student':renderStudent();break;case 'tutor':renderTutor();break;case 'learn':renderLesson(id);break;case 'quiz':renderQuiz();break;case 'cases':renderCases();break;case 'case':renderCase(Number(id));break;case 'resources':renderResources();break;case 'certificate':renderCertificate();break;case 'builder':renderBuilder();break;case 'editor':renderEditor(id);break;case 'students':renderStudents();break;case 'review':renderReviews(id,caseIndex);break;case 'reviews':renderReviews();break;default:go(session.role==='tutor'?'tutor':'student');return;}
 window.scrollTo({top:0,behavior:'instant'});
}
document.querySelector('#reset-cancel').addEventListener('click',()=>document.querySelector('#reset-dialog').close());
document.querySelector('#reset-confirm').addEventListener('click',async()=>{const dialog=document.querySelector('#reset-dialog');state=createState();persist();session=null;remember();dialog.close();try{const db=await openDb();await new Promise((resolve,reject)=>{const tx=db.transaction('files','readwrite');tx.objectStore('files').clear();tx.oncomplete=resolve;tx.onerror=reject;});db.close();}catch{}go('login');toast('The original example accounts and course have been restored.');});
document.querySelector('#remove-cancel').addEventListener('click',()=>document.querySelector('#remove-dialog').close());
document.querySelector('#remove-confirm').addEventListener('click',()=>{const dialog=document.querySelector('#remove-dialog'),id=dialog.dataset.lesson;state.course.lessons=state.course.lessons.filter(l=>l.id!==id);state.students.forEach(s=>{s.completed=s.completed.filter(x=>x!==id);delete s.notes[id];});persist();dialog.close();go('builder');toast('Lesson removed from this demonstration.');});
document.querySelector('.skip-link').addEventListener('click',e=>{e.preventDefault();const main=document.querySelector('#portal-main');main?.focus();main?.scrollIntoView({block:'start'});});
window.addEventListener('hashchange',render);
window.addEventListener('storage',event=>{if(event.key===STORAGE_KEY){try{const next=JSON.parse(event.newValue);if(next?.version===2){state=next;if(!['editor','case'].includes(location.hash.slice(1).split('/')[0]))render();}}catch{}}});
render();
